**2. `lib/supabase/server.ts`**
```typescript
import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

export async function createClient() {
  const cookieStore = await cookies()
  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll()
        },
        setAll(cookiesToSet, _headers) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            )
          } catch {
            // called from a Server Component; ignore if middleware/proxy refreshes sessions
          }
        },
      },
    }
  )
}
```

**3. `lib/supabase/proxy.ts`** (the `updateSession` helper — Supabase's docs already use `proxy` terminology, not `middleware`)
```typescript
import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function updateSession(request: NextRequest) {
  let supabaseResponse = NextResponse.next({ request })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet, headers) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({ request })
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
          Object.entries(headers).forEach(([key, value]) =>
            supabaseResponse.headers.set(key, value)
          )
        },
      },
    }
  )

  // Do not run code between createServerClient and supabase.auth.getClaims().
  const { data } = await supabase.auth.getClaims()
  const user = data?.claims

  if (!user && !request.nextUrl.pathname.startsWith('/login') && !request.nextUrl.pathname.startsWith('/auth')) {
    const url = request.nextUrl.clone()
    url.pathname = '/login'
    return NextResponse.redirect(url)
  }

  // Must return supabaseResponse as-is (or copy its cookies) — mutating it wrong desyncs browser/server sessions.
  return supabaseResponse
}
```

**4. Root `proxy.ts`**
```typescript
import { type NextRequest } from 'next/server'
import { updateSession } from '@/lib/supabase/proxy'

export async function proxy(request: NextRequest) {
  return await updateSession(request)
}

export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)',
  ],
}
```

**5. `getClaims()` vs `getUser()`**: Docs mandate `getClaims()` in Proxy/middleware ("*Never* trust `getSession()`... It's safe to trust `getClaims()` because it validates the JWT signature against the project's published public keys every time"). No symmetric/legacy-JWT fallback is mentioned — `getClaims()` is presented as the current universal recommendation, no branching by key type. Separately, the FAQ notes `getClaims()` only does local signature/expiry validation and does **not** confirm server-side logout — for that, `getUser()` is required (extra round trip). So: use `getClaims()` in Proxy for the common refresh/redirect check; use `getUser()` only where you must positively confirm the session hasn't been revoked server-side.

**6. Server Action signatures** (`app/login/actions.ts`)
```typescript
'use server'
import { redirect } from 'next/navigation'
import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'

export async function login(formData: FormData) {
  const supabase = await createClient()
  const data = { email: formData.get('email') as string, password: formData.get('password') as string }
  const { error } = await supabase.auth.signInWithPassword(data)
  if (error) redirect('/error')
  revalidatePath('/', 'layout')
  redirect('/account')
}

export async function signup(formData: FormData) {
  const supabase = await createClient()
  const data = { email: formData.get('email') as string, password: formData.get('password') as string }
  const { error } = await supabase.auth.signUp(data)
  if (error) redirect('/error')
  revalidatePath('/', 'layout')
  redirect('/account')
}
```
No `emailRedirectTo` option appears in this example — signUp is called bare with just `{email, password}`.

**Surprises**: (a) Supabase's own current docs already use `proxy.ts`/`export async function proxy` — they've adopted the Next.js 16 rename, so no naming translation needed. (b) `@supabase/ssr` is explicitly confirmed **not deprecated** — there's a newer sibling package `@supabase/server` for header/Bearer-JWT auth (Edge Functions etc.), but cookie-based Next.js apps should keep using `@supabase/ssr`. (c) Env var convention has shifted to `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY` (not `ANON_KEY`) in current examples, with legacy anon keys still supported through end of 2026.
